def factorial(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1  # base case
    return n * factorial(n - 1)  # general case

print(factorial(5))  # 120

def binary_search(items, target, low, high):
    if low > high:
        return -1                      # base case: not found
    mid = (low + high) // 2
    if items[mid] == target:
        return mid                     # base case: found
    if target < items[mid]:
        return binary_search(items, target, low, mid - 1)
    return binary_search(items, target, mid + 1, high)

data = [3, 8, 15, 21, 34, 47, 52]
print(binary_search(data, 34, 0, 6))  # 4
print(binary_search(data, 10, 0, 6))  # -1

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def insert(node, data):
    if node is None:
        return Node(data)              # base case: empty place found
    if data < node.data:
        node.left = insert(node.left, data)
    else:
        node.right = insert(node.right, data)
    return node

def in_order(node):
    if node is None:
        return                         # base case: nothing to visit
    in_order(node.left)
    print(node.data, end=" ")
    in_order(node.right)

root = None
for value in [40, 25, 60, 10, 30]:
    root = insert(root, value)
in_order(root)  # 10 25 30 40 60
